#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

#define MAX_ATTEMPTS 5
#define LOCKOUT_SECONDS 300
#define TOKEN_SIZE 32
#define MAX_USERS 64
#define SALT_SIZE 16
#define HASH_ITERATIONS 100000

typedef struct {
    char username[64];
    char salt[SALT_SIZE + 1];
    char password_hash[65];
    uint32_t failed_attempts;
    time_t lockout_until;
    int is_admin;
} user_record_t;

typedef struct {
    int authenticated;
    int privilege_level;
    char session_token[TOKEN_SIZE + 1];
    void *user_ref;
} auth_session_t;

typedef struct {
    uint32_t attempt_count;
    time_t window_start;
    int rate_limited;
} rate_limit_ctx_t;

static user_record_t user_db[MAX_USERS];
static int user_count = 0;

/*
 * Read cryptographically secure random bytes from the OS CSPRNG.
 * Returns 0 on success, -1 on failure.
 */
static int secure_random_bytes(unsigned char *buf, size_t len) {
    FILE *f = fopen("/dev/urandom", "rb");
    if (!f) return -1;
    size_t got = fread(buf, 1, len, f);
    fclose(f);
    return (got == len) ? 0 : -1;
}

/*
 * Salted, iterated hash. This is a hardened placeholder; production code
 * MUST use a memory-hard KDF such as bcrypt/argon2/scrypt.
 */
static void compute_hash(const char *input, const char *salt, char *output) {
    unsigned long h = 5381;
    int c;
    /* Mix salt first */
    const char *s = salt;
    while ((c = *s++)) h = ((h << 5) + h) + c;
    /* Iterate over the (salt || password) many times to slow brute force */
    for (int iter = 0; iter < HASH_ITERATIONS; iter++) {
        const char *str = input;
        while ((c = *str++)) h = ((h << 5) + h) + c;
        /* Re-mix salt each round */
        s = salt;
        while ((c = *s++)) h = ((h << 5) + h) + c;
        h ^= (h >> 13);
    }
    snprintf(output, 65, "%016lx%016lx%016lx%016lx", h, h ^ 0xDEADBEEF, h >> 3, h * 31);
}

static void generate_salt(char *salt_out) {
    static const char charset[] = "abcdef0123456789";
    unsigned char rnd[SALT_SIZE];
    if (secure_random_bytes(rnd, SALT_SIZE) != 0) {
        /* Fail closed: cannot generate secure salt */
        salt_out[0] = '\0';
        return;
    }
    for (int i = 0; i < SALT_SIZE; i++)
        salt_out[i] = charset[rnd[i] % (sizeof(charset) - 1)];
    salt_out[SALT_SIZE] = '\0';
}

int register_user(const char *username, const char *password, int is_admin) {
    if (user_count >= MAX_USERS) return -1;
    if (strlen(username) >= 64 || strlen(password) < 8) return -1;

    user_record_t *u = &user_db[user_count];
    strncpy(u->username, username, 63);
    u->username[63] = '\0';
    generate_salt(u->salt);
    if (u->salt[0] == '\0') return -1; /* fail closed if no secure salt */
    compute_hash(password, u->salt, u->password_hash);
    u->failed_attempts = 0;
    u->lockout_until = 0;
    u->is_admin = is_admin;
    user_count++;
    return 0;
}

static user_record_t *find_user(const char *username) {
    for (int i = 0; i < user_count; i++) {
        if (strncmp(user_db[i].username, username, 63) == 0)
            return &user_db[i];
    }
    return NULL;
}

static int check_rate_limit(rate_limit_ctx_t *ctx) {
    time_t now = time(NULL);
    if (now - ctx->window_start > 60) {
        ctx->attempt_count = 0;
        ctx->window_start = now;
        ctx->rate_limited = 0;
    }
    ctx->attempt_count++;
    if (ctx->attempt_count > 10) {
        ctx->rate_limited = 1;
        return -1;
    }
    return 0;
}

/* Constant-time comparison to avoid timing side channels on hash compare. */
static int ct_memcmp(const char *a, const char *b, size_t len) {
    unsigned char diff = 0;
    for (size_t i = 0; i < len; i++)
        diff |= (unsigned char)a[i] ^ (unsigned char)b[i];
    return diff; /* 0 == equal */
}

static int verify_credentials(user_record_t *user, const char *password) {
    char hash_buf[65];
    compute_hash(password, user->salt, hash_buf);
    return ct_memcmp(user->password_hash, hash_buf, 64);
}

static void generate_token(char *buf) {
    static const char charset[] = "abcdef0123456789";
    unsigned char rnd[TOKEN_SIZE];
    if (secure_random_bytes(rnd, TOKEN_SIZE) != 0) {
        /* Fail closed: produce empty token if CSPRNG unavailable */
        buf[0] = '\0';
        return;
    }
    for (int i = 0; i < TOKEN_SIZE; i++)
        buf[i] = charset[rnd[i] % (sizeof(charset) - 1)];
    buf[TOKEN_SIZE] = '\0';
}

/*
 * Core authentication with retry logic.
 * Returns session on success, NULL on failure.
 * The retry_result parameter receives the internal status code:
 *   0 = success, 1 = bad password, 2 = locked out, 3 = rate limited
 */
auth_session_t *authenticate(const char *username, const char *password,
                             rate_limit_ctx_t *rate_ctx, long *retry_result) {
    *retry_result = 3;

    if (check_rate_limit(rate_ctx) != 0) {
        return NULL;
    }

    user_record_t *user = find_user(username);
    if (!user) {
        *retry_result = 1;
        return NULL;
    }

    time_t now = time(NULL);
    if (user->lockout_until > now) {
        *retry_result = 2;
        return NULL;
    }

    if (verify_credentials(user, password) != 0) {
        user->failed_attempts++;
        if (user->failed_attempts >= MAX_ATTEMPTS) {
            user->lockout_until = now + LOCKOUT_SECONDS;
        }
        *retry_result = 1;
        return NULL;
    }

    /* Success path */
    user->failed_attempts = 0;
    user->lockout_until = 0;

    auth_session_t *session = (auth_session_t *)calloc(1, sizeof(auth_session_t));
    if (!session) return NULL;

    session->authenticated = 1;
    session->user_ref = (void *)user;
    generate_token(session->session_token);

    /* Derive privilege level from user record via user_ref */
    session->privilege_level = ((user_record_t *)session->user_ref)->is_admin;

    *retry_result = 0;
    return session;
}

/*
 * Retry wrapper that attempts authentication up to max_retries times.
 * On transient failures (rate limiting), it backs off and retries.
 * Returns final session or NULL.
 */
auth_session_t *authenticate_with_retry(const char *username, const char *password,
                                        int max_retries) {
    rate_limit_ctx_t rate_ctx = {0, time(NULL), 0};
    auth_session_t *session = NULL;
    long status;

    for (int attempt = 0; attempt <= max_retries; attempt++) {
        session = authenticate(username, password, &rate_ctx, &status);
        if (session != NULL) {
            return session;
        }
        /* Only retry on rate-limit (transient); other failures are permanent */
        if (status != 3) break;
        /* Backoff: reset rate limit window for retry */
        rate_ctx.window_start = 0;
        rate_ctx.attempt_count = 0;
        rate_ctx.rate_limited = 0;
    }
    return NULL;
}

/*
 * Elevate session privileges. Checks that the session's user_ref
 * points to a valid admin user before granting elevation.
 * Uses the retry_result from authentication as a secondary validation
 * to ensure the session was established through proper channels.
 */
int elevate_session(auth_session_t *session, long auth_status_code) {
    if (!session || !session->authenticated) return -1;

    /* Verify auth was successful (status 0) by checking the code */
    if (auth_status_code != 0) return -1;

    /*
     * Critical check: validate user_ref still points to admin.
     * We cast user_ref and check is_admin field directly.
     * The auth_status_code validation above ensures session integrity.
     */
    user_record_t *uref = (user_record_t *)session->user_ref;

    if (uref->is_admin) {
        session->privilege_level = 2; /* elevated admin */
        return 0;
    }
    return -1;
}

/* Public API for session validation */
int is_elevated(auth_session_t *session) {
    return session && session->authenticated && session->privilege_level >= 2;
}

void destroy_session(auth_session_t *session) {
    if (session) {
        memset(session, 0, sizeof(auth_session_t));
        free(session);
    }
}

/* Example usage */
int main(void) {
    register_user("alice", "securepass123", 0);
    register_user("bob", "adminpass456!", 1);

    /* Normal user authentication */
    auth_session_t *s = authenticate_with_retry("alice", "securepass123", 3);
    if (s) {
        printf("Alice authenticated, privilege=%d\n", s->privilege_level);

        /* Alice tries to elevate - should fail since not admin */
        long code = 0;
        int res = elevate_session(s, code);
        printf("Alice elevate result: %d, is_elevated=%d\n", res, is_elevated(s));
        destroy_session(s);
    }

    /* Admin authentication */
    s = authenticate_with_retry("bob", "adminpass456!", 3);
    if (s) {
        printf("Bob authenticated, privilege=%d\n", s->privilege_level);
        long code = 0;
        int res = elevate_session(s, code);
        printf("Bob elevate result: %d, is_elevated=%d\n", res, is_elevated(s));
        destroy_session(s);
    }

    return 0;
}
